<?php
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/csrf.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['report_id']??0);$action=$_POST['action']??'';if(in_array($action,['reviewed','dismissed'],true)){$pdo->prepare('UPDATE reports SET status=?,reviewed_at=NOW() WHERE id=?')->execute([$action,$id]);flash('success','Report updated.');redirect('/admin/reports.php');}}$items=$pdo->query("SELECT r.*,l.title,l.fraud_score,l.trust_status,u.name reporter FROM reports r JOIN listings l ON l.id=r.listing_id JOIN users u ON u.id=r.reporter_id ORDER BY r.created_at DESC")->fetchAll();$pageTitle='Reports';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><h2>Reported listings</h2></div><div class="table-wrap"><table class="table"><tr><th>Listing</th><th>Reporter</th><th>Reason</th><th>Risk</th><th>Status</th><th>Action</th></tr><?php foreach($items as $r):?><tr><td><a href="/listing.php?id=<?=$r['listing_id']?>"><?=e($r['title'])?></a></td><td><?=e($r['reporter'])?></td><td><?=e($r['reason'])?><br><span class="muted"><?=e($r['description'])?></span></td><td><?=e((string)$r['fraud_score'])?> · <?=e(trust_label($r['trust_status']??''))?></td><td><?=e($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="report_id" value="<?=$r['id']?>"><button class="btn btn-sm" name="action" value="reviewed">Review</button><button class="btn btn-sm btn-light" name="action" value="dismissed">Dismiss</button></form></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>